import React, { useState } from 'react';
import { useSelector } from 'react-redux';

const Dashboard = () => {
  const { user } = useSelector((state) => state.auth);
  const [showProfile, setShowProfile] = useState(false);
  const [profileData, setProfileData] = useState({
    fullName: user?.fullName || '',
    email: user?.email || '',
    phone: user?.phone || ''
  });

  const handleProfileUpdate = () => {
    alert('Profile updated successfully!');
    setShowProfile(false);
  };

  return (
    <div style={{ 
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', 
      minHeight: '100vh', 
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
      padding: '0',
      margin: '0',
      overflow: 'hidden'
    }}>
      {/* Mobile Header */}
      <div style={{
        background: 'rgba(255, 255, 255, 0.95)',
        backdropFilter: 'blur(10px)',
        padding: '15px 20px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        borderBottom: '1px solid rgba(255, 255, 255, 0.2)',
        position: 'sticky',
        top: '0',
        zIndex: '100'
      }}>
        <div>
          <h1 style={{ margin: '0', color: '#333', fontSize: '20px', fontWeight: '600' }}>NIVRA</h1>
          <p style={{ margin: '0', color: '#666', fontSize: '12px' }}>Hi, {user?.fullName?.split(' ')[0] || 'User'}!</p>
        </div>
        <button 
          onClick={() => setShowProfile(!showProfile)}
          style={{
            background: '#ff6b9d',
            color: 'white',
            border: 'none',
            padding: '8px 16px',
            borderRadius: '20px',
            fontSize: '14px',
            fontWeight: '500'
          }}
        >
          👤
        </button>
      </div>

      {/* Scrollable Content */}
      <div style={{ 
        height: 'calc(100vh - 70px)', 
        overflowY: 'auto', 
        padding: '20px',
        paddingBottom: '100px'
      }}>

        {/* Profile Section */}
        {showProfile && (
          <div style={{
            background: 'white',
            borderRadius: '20px',
            padding: '20px',
            marginBottom: '20px',
            boxShadow: '0 10px 30px rgba(0,0,0,0.1)'
          }}>
            <h3 style={{ margin: '0 0 20px 0', color: '#333', fontSize: '18px' }}>Edit Profile</h3>
